"""Structured PHB actions and weapon properties, independent of application labels."""
from curated import record


def actions():
    rows=[
      ('attack','Attack','Attaccare',193,{'activation':'action','attacks':1,'extraAttacks':'only-from-applicable-feature'},'Un attacco da mischia o a distanza; i privilegi possono aumentarne il numero.'),
      ('cast-a-spell','Cast a Spell','Lanciare un Incantesimo',193,{'activation':'spell-casting-time'},'Il tempo del singolo incantesimo determina quale risorsa del turno serve.'),
      ('dash','Dash','Scattare',193,{'activation':'action','additionalMovement':'current-speed','expires':'end-of-turn'},'Aggiungi movimento pari alla velocità attuale, dopo i modificatori.'),
      ('disengage','Disengage','Disimpegnarsi',193,{'activation':'action','movementProvokesOpportunity':False,'expires':'end-of-turn'},'Il movimento non provoca attacchi di opportunità per il resto del turno.'),
      ('dodge','Dodge','Schivare',193,{'activation':'action','expires':'start-of-next-turn','attackersDisadvantage':'if-you-see-attacker','dexteritySaveAdvantage':True,'lostWhen':['incapacitated','speed-zero']},'Ostacoli gli attacchi visibili e migliori i TS di Destrezza finché puoi agire e muoverti.'),
      ('help','Help','Aiutare',193,{'activation':'action','expires':'start-of-next-turn','check':'next-check-for-assisted-task','attack':'first-ally-attack-on-target-within-5-ft-of-helper','advantage':True},'Favorisci una prova del compagno o il suo primo attacco contro un bersaglio vicino a te.'),
      ('hide','Hide','Nascondersi',[178,193,195],{'activation':'action','check':{'ability':'dexterity','skill':'stealth'},'eligibility':'DM-determines-and-cannot-be-clearly-seen','comparison':'perception-or-passive-perception'},'Nascondersi richiede condizioni adatte e una prova, non una CD fissa.'),
      ('ready','Ready','Preparare',194,{'activation':'action','trigger':'perceivable','release':'reaction-after-trigger-finishes','mayIgnoreTrigger':True,'responseChoice':['action','move-up-to-speed'],'expiresInLocalPrinting':'later-in-the-round','spell':{'castingTimeRequired':'1-action','castImmediately':True,'concentrationRequired':True,'lostIfConcentrationBroken':True}},'Scegli evento percepibile e risposta con azione oppure movimento. Dopo evento puoi usare reazione o ignorarlo. Magia di un’azione lanciata subito e trattenuta con concentrazione, persa se interrotta.'),
      ('search','Search','Cercare',194,{'activation':'action','DMChoosesCheck':[['wisdom','perception'],['intelligence','investigation']]},'Il tipo di ricerca determina se serve Percezione o Indagare.'),
      ('use-an-object','Use an Object','Usare un Oggetto',[190,194],{'activation':'action','requiredWhen':['item-requires-action','additional-object-interaction']},'Un uso che richiede azione o un’interazione ulteriore consuma questa azione.'),
    ]
    return [record('action',i,n,it,p,m,s) for i,n,it,p,m,s in rows]


def properties():
    rows=[
      ('ammunition','Ammunition','Munizioni',[147,148],{'expendedPerAttack':1,'recoverFraction':0.5,'searchMinutes':1,'meleeUse':'improvised'},'Servono munizioni; un minuto di ricerca dopo lo scontro ne recupera metà.'),
      ('finesse','Finesse','Accurata',148,{'abilityChoice':['strength','dexterity'],'sameAbilityForAttackAndDamage':True},'Puoi scegliere Forza o Destrezza, mantenendo la scelta per attacco e danni.'),
      ('heavy','Heavy','Pesante',148,{'smallCreaturesAttackDisadvantage':True},'Le creature Piccole hanno svantaggio; non applicare i requisiti di Forza del 2024.'),
      ('light','Light','Leggera',148,{'enables':'two-weapon-fighting-with-other-light-melee-weapon'},'La proprietà permette il combattimento con due armi secondo i relativi requisiti.'),
      ('loading','Loading','Ricarica',148,{'maxAmmunitionPerActivation':1,'activations':['action','bonus-action','reaction']},'Limita il numero di proiettili per singola azione, azione bonus o reazione.'),
      ('range','Range','Gittata',148,{'beyondNormal':'disadvantage','beyondLong':'cannot-attack','unit':'ft'},'Le due distanze rappresentano gittata normale e massima.'),
      ('reach','Reach','Portata',148,{'attackReachBonusFt':5,'opportunityReach':None},'Questa stampa menziona l’aumento per gli attacchi. L’applicazione agli attacchi di opportunità va documentata attraverso il rimando alle regole del combattimento.'),
      ('special','Special','Speciale',[148,149],{'weaponSpecific':True},'Consulta le regole proprie di lancia da cavaliere e rete.'),
      ('thrown','Thrown','Lancio',148,{'enables':'ranged-attack','meleeWeaponAbility':'same-as-melee-attack'},'Un’arma da mischia lanciata mantiene la caratteristica usata negli attacchi da mischia.'),
      ('two-handed','Two-Handed','A Due Mani',148,{'handsToUse':2},'L’uso dell’arma richiede entrambe le mani.'),
      ('versatile','Versatile','Versatile',148,{'handsChoice':[1,2],'twoHandMeleeDamage':'weapon-specific'},'Il dado indicato tra parentesi vale per l’attacco da mischia con due mani.'),
    ]
    return [record('weapon-property',i,n,it,p,m,s,missing=['opportunityReach'] if i=='reach' else None) for i,n,it,p,m,s in rows]


def additional_rules():
    rows=[
      ('score-generation','Generating Ability Scores','Generare le Caratteristiche',[14],{'random':{'diceCount':4,'die':6,'keepHighest':3,'repeat':6},'standardArray':[15,14,13,12,10,8],'pointBuy':{'optional':True,'budget':27,'minimum':8,'maximum':15,'costs':{'8':0,'9':1,'10':2,'11':3,'12':4,'13':5,'14':7,'15':9}}},'Assegna liberamente i risultati; applica poi gli incrementi razziali. L’acquisto a punti è una variante.'),
      ('turn-economy','Your Turn, Bonus Actions, Reactions','Economia del Turno',[190,191],{'roundSeconds':6,'normalActions':1,'move':'up-to-speed','bonusActionMaximum':1,'bonusActionRequires':'explicit-feature','cannotTakeActionsAlsoPreventsBonus':True,'reactionMaximumUntilNextTurn':1,'reactionRecovers':'start-of-own-turn','reactionMayOccur':'own-or-another-turn','freeObjectInteractions':1,'additionalInteraction':'Use-an-Object-action','specialCareOrObstacle':'DM-may-require-action','briefCommunication':'no-action','interruptedTurn':'continues-after-reaction'},'Un’azione e movimento, un bonus solo da capacità. Impedimento ad azioni impedisce bonus. Una reazione recuperata a inizio turno, anche nel proprio; turno interrotto prosegue. Interazione singola gratuita, seconda con azione; il DM può richiedere azione per ostacoli.'),
      ('movement','Movement and Position','Movimento',[191,192,193],{'canSplitBeforeAfterAttacks':True,'difficultTerrainExtraFtPerFt':1,'difficultTerrainMultipleSourcesStack':False,'crawlExtraFtPerFt':1,'dropProneCost':0,'standCost':'half-current-speed','standRequiresEnoughMovement':True,'cannotStandAtSpeedZero':True,'switchSpeed':'subtract-movement-already-used','otherCreatureSpace':'difficult-terrain','nonhostileSpacePassage':True,'hostileSpacePassage':'at-least-two-sizes-larger-or-smaller','cannotWillinglyEndInOtherSpace':True,'flyFallsWhen':['prone','speed-zero','cannot-move'],'flyFallException':['hover','held-aloft-by-magic']},'Movimento fra azioni e attacchi; terreno difficile e strisciare sommano costi. Prono gratis, rialzarsi metà velocità con movimento sufficiente. Attraversare ostili solo se distano almeno due taglie; nessuna sosta volontaria in altri spazi. Volo cade a zero velocità, prono o immobilità salvo fluttuare o sostegno magico.'),
      ('special-weapons','Special Weapons','Armi Speciali',[149],{'lance':{'disadvantageWithinFt':5,'handsUnlessMounted':2},'net':{'maxTargetSize':'Large','noEffectOn':'formless','condition':'restrained','escape':{'activation':'action','strengthDC':10},'destroy':{'AC':10,'slashingDamage':5},'maxAttacksPerActivation':1}},'La rete limita a un attacco per attivazione e può essere rimossa con una prova o distrutta.'),
      ('improvised-weapons','Improvised Weapons','Armi Improvvisate',[148,149],{'defaultDamage':'1d4','damageType':'DM-choice','thrownRangeFt':{'normal':20,'long':60},'similarWeapon':'DM-may-treat-as-that-weapon'},'Il DM può riconoscere un’arma simile; altrimenti usa il danno base dell’arma improvvisata.'),
      ('silvering','Silvered Weapons','Argentare Armi',[149],{'costGP':100,'choice':['one-weapon','ten-ammunition']},'Il costo include materiali e lavorazione.'),
      ('carrying-capacity','Lifting and Carrying','Capacità di Carico',[177],{'carryingLbPerStrength':15,'pushDragLiftLbPerStrength':30,'tinyMultiplier':0.5,'multiplierPerSizeAboveMedium':2,'pushDragAboveCarryingSpeedFt':5},'La taglia modifica carico e sollevamento; il trascinamento oltre la capacità riduce la velocità.'),
      ('combat-initiative-surprise','Initiative and Surprise','Iniziativa e Sorpresa',[190],{'initiative':'dexterity-check-highest-first','identicalMonsterGroup':'one-roll-and-same-initiative','orderFixedAcrossRounds':True,'tieOrder':'players-among-PCs; DM-among-NPCs-and-mixed; optional-new-d20-highest-first','surprise':'DM-individually-compares-hidden-Stealth-with-opponents-passive-Perception','noStealth':'automatically-notice-each-other','surprisedFirstTurn':['no-movement','no-action'],'surprisedReactionUnavailableUntil':'end-first-turn','groupMembersMayDiffer':True},'Iniziativa è prova Destrezza con ordine fisso; gruppi identici un tiro. Sorpresa decisa individualmente dal DM: primo turno senza azione o movimento, niente reazioni finché termina. Pareggi fra PG decisi dai giocatori, altri dal DM, oppure nuovo d20.'),
      ('attack-rolls','Making an Attack','Tiri di Attacco',[194,195],{'steps':['choose-target-in-range','determine-cover-advantage-and-modifiers','roll-and-apply-specific-effects'],'targets':['creature','object','location'],'attack':'d20-plus-ability-and-proficiency-if-applicable','hit':'total-at-least-AC','naturalTwenty':'hit-and-critical-regardless-AC','naturalOne':'miss-regardless-modifiers','weaponMeleeAbility':'strength','weaponRangedAbility':'dexterity','exceptions':['finesse','thrown'],'spellAbility':'casting-ability','monsterModifiers':'printed-stat-block','attackRollAlwaysCountsAsAttack':True},'Scegli bersaglio valido, modificatori e tira. Totale almeno CA colpisce; uno naturale manca e venti naturale colpisce critico. Competenza se arma competente o incantesimo; caratteristiche secondo tipo e proprietà, mostri usano bonus stampati.'),
      ('unseen-attackers','Unseen Attackers and Targets','Attaccanti e Bersagli Non Visti',[195,196],{'cannotSeeTarget':'attack-disadvantage','targetNotAtGuessedLocation':'automatic-miss-DM-need-not-reveal-why','targetCannotSeeAttacker':'attack-advantage','hiddenMeaning':['unseen','unheard'],'hiddenAttackRevealsLocation':'hit-or-miss'},'Non vedere bersaglio dà svantaggio; non essere visto dà vantaggio. Bersaglio assente dal luogo scelto mancato automaticamente. Un attacco rivela posizione di chi è nascosto, anche se manca.'),
      ('creature-space','Creature Size and Space','Spazio delle Creature',[192,193],{'controlledSquareSideFt':{'Tiny':2.5,'Small':5,'Medium':5,'Large':10,'Huge':15,'Gargantuan':20},'GargantuanMayBeLarger':True,'spaceIs':'controlled-area-not-body-dimensions','surroundingMediumExamples':{'MediumAroundOneMedium':8,'LargeAroundOneMediumInLocalPrinting':5,'MediumAroundGargantuan':20},'gridVariant':{'optional':True,'squareSideFt':5,'diagonalCostSquares':1,'cannotCross':'filled-terrain-corner','entryRequires':'enough-movement-for-whole-cost','range':'shortest-route-count-adjacent-to-start-through-target-space'}},'Spazio controllato: Minuscola due piedi e mezzo; Piccola/Media cinque; Grande dieci; Enorme quindici; Mastodontica venti o più. Variante griglia cinque piedi e diagonali di un quadretto, senza tagliare angoli pieni. L’esempio cinque Grandi intorno a Media viene corretto dalle errata.'),
      ('squeezing','Squeezing into a Smaller Space','Stringersi in Spazi Ridotti',[193],{'minimumPassage':'space-for-one-size-smaller-creature','extraMovementFtPerFt':1,'ownAttackRolls':'disadvantage','ownDexteritySaves':'disadvantage','attacksAgainst':'advantage'},'Può attraversare spazio della taglia immediatamente inferiore spendendo un piede extra per piede, svantaggio ad attacchi e TS Destrezza, vantaggio agli attacchi contro sé.'),
      ('damage-rolls','Damage Rolls and Hit Points','Danni e Punti Ferita',[197],{'weaponDamageAbility':'same-modifier-as-attack','spellDamage':'specified-by-spell','simultaneousMultiTargetDamage':'one-damage-roll-for-all','HPBounds':'zero-to-maximum','HPLossAffectsCapabilities':'only-at-zero-unless-specific-rule','damageTypes':['acid','bludgeoning','cold','fire','force','lightning','necrotic','piercing','poison','psychic','radiant','slashing','thunder'],'typesHaveNoStandaloneRules':True},'Danno dell’arma aggiunge stessa caratteristica dell’attacco; magie specificano propri dadi e modificatori. Danni simultanei a più bersagli un solo tiro. Perdita PF non limita capacità prima di zero salvo eccezioni; tredici tipi collegano resistenze e altri effetti.'),
      ('zero-hp-stability','Dropping to Zero and Stabilizing','Zero PF e Stabilizzazione',[198,199],{'atZeroWithoutInstantDeath':'unconscious-until-any-HP-regained','deathSaveTiming':'start-own-turn-at-zero-unless-stable','deathSaveAbility':None,'notConsecutiveRequired':True,'stable':'zero-HP-unconscious-no-death-saves','stableAfterDamage':'no-longer-stable-resume-death-saves','stableUnhealedRecovery':'one-HP-after-1d4-hours','monstersDefault':'DM-usually-death-at-zero-important-NPCs-may-use-death-saves'},'A zero senza morte istantanea si perde coscienza fino a guarire. TS morte a inizio turno senza caratteristica, esiti non necessariamente consecutivi. Stabile resta incosciente senza TS; nuovo danno annulla stabilità. Se non curato recupera un PF dopo d4 ore. Mostri di solito muoiono a zero, scelta del DM.'),
      ('knocking-out','Knocking a Creature Out','Mettere Fuori Combattimento',[199],{'trigger':'melee-attack-reduces-creature-to-zero-HP','choiceTiming':'instant-damage-dealt','result':['unconscious','stable'],'requiresWeaponAttack':False},'Riducendo a zero con attacco in mischia, anche magico, puoi scegliere in quel momento di lasciare creatura incosciente e stabile.'),
      ('temporary-hp','Temporary Hit Points','Punti Ferita Temporanei',[199],{'absorbsDamageBeforeNormalHP':True,'canExceedNormalMaximum':True,'cannotBeHealed':True,'multipleGrants':'choose-old-or-new-no-stacking','atZero':'do-not-restore-consciousness-or-stabilize-but-can-absorb-damage','defaultEnd':['depleted','finish-long-rest'],'specificGrantDurationOverrides':True},'PF temporanei assorbono prima i danni, non si curano né sommano. Nuova concessione permette scegliere vecchi o nuovi. A zero non risvegliano o stabilizzano. Senza durata propria terminano consumati o al termine del riposo lungo.'),
      ('mounted-combat','Mounted Combat','Combattimento in Sella',[199],{'mountRequires':['willing','at-least-one-size-larger','appropriate-anatomy'],'mountDismount':{'maximumDuringMove':1,'mountWithinFt':5,'cost':'half-own-speed','requires':'nonzero-speed-and-enough-movement'},'involuntaryMountMoveOrRiderProne':{'saveAbility':'dexterity','saveDC':10,'failure':'dismounted-prone-within-five-ft'},'mountProne':'reaction-dismount-to-feet-or-dismounted-prone-within-five-ft','controlledMount':{'requires':'trained-to-accept-rider','initiative':'matches-rider-on-mounting','moves':'as-directed','actions':['Dash','Disengage','Dodge'],'canActOnMountingTurn':True},'intelligentMount':'independent','independentMount':'own-initiative-unrestricted-actions-own-movement-decisions','mountProvokesOpportunity':'attacker-may-target-mount-or-rider'},'Cavalcatura consenziente, anatomia adatta e almeno una taglia maggiore. Salire o scendere una volta nel movimento costa metà velocità; cadute richiedono TS Destrezza dieci o reazione se cavalcatura prona. Controllata e addestrata condivide iniziativa e usa Scattare, Disimpegnarsi o Schivare; intelligente indipendente. Opportunità provocata dalla cavalcatura può colpire cavaliere.'),
      ('underwater-combat','Underwater Combat','Combattimento Sott’Acqua',[199],{'withoutSwimSpeedMeleeWeaponAttack':'disadvantage','meleeExceptions':['dagger','javelin','shortsword','spear','trident'],'rangedWeaponBeyondNormalRange':'automatic-miss','rangedWeaponWithinNormal':'disadvantage','rangedExceptions':['crossbow','net','javelin-like-thrown-weapon-including-spear-trident-dart'],'fullyImmersedCreaturesAndObjects':'fire-resistance','theseAttackPenaltiesApplyTo':'weapon-attacks-not-spell-attacks'},'Senza velocità nuoto, svantaggio a mischia con armi salvo cinque eccezioni. Armi a distanza mancano oltre gittata normale e hanno svantaggio entro, salvo balestre, reti e lanci tipo giavellotto. Creature e oggetti interamente immersi resistono al fuoco. Le penalità indicate riguardano attacchi con armi.'),
      ('unarmed-strikes','Unarmed Strikes','Colpi Senz’Armi',[150,196,197],{'listedAsWeaponInLocalPrinting':True,'weaponCategoryInLocalPrinting':'simple-melee','baseDamage':1,'damageType':'bludgeoning','damageAbility':'strength','proficiencyInLocalPrinting':'simple-weapon-proficiency','correctedRulePending':True},'La tabella della copia locale classifica il colpo senz’armi come semplice da mischia, danno uno contundente più Forza. Le errata lo rimuovono come arma e concedono competenza universale senza trasformarlo in oggetto.'),
    ]
    return [record('rule',i,n,it,p,m,s) for i,n,it,p,m,s in rows]


